```yaml name=docker-compose.yml
version: "3.8"
services:
  db:
    image: mysql:8.0
    restart: unless-stopped
    environment:
      MYSQL_ROOT_PASSWORD: secret
      MYSQL_DATABASE: pulse
      MYSQL_USER: pulse
      MYSQL_PASSWORD: secret
    ports:
      - "3306:3306"
    volumes:
      - dbdata:/var/lib/mysql

  backend:
    build:
      context: ./backend
      dockerfile: Dockerfile
    image: pulse_backend
    depends_on:
      - db
    environment:
      DB_HOST: db
      DB_DATABASE: pulse
      DB_USERNAME: pulse
      DB_PASSWORD: secret
    volumes:
      - ./backend:/var/www
    ports:
      - "9000:9000"

  nginx:
    image: nginx:stable
    depends_on:
      - backend
    volumes:
      - ./backend/nginx/default.conf:/etc/nginx/conf.d/default.conf:ro
      - ./backend:/var/www
    ports:
      - "8080:80"

  frontend:
    build:
      context: ./frontend
      dockerfile: Dockerfile
    image: pulse_frontend
    volumes:
      - ./frontend:/app
    ports:
      - "5173:5173"
    command: ["npm","run","dev"]

volumes:
  dbdata:
