const { Sequelize, DataTypes } = require('sequelize');
const path = require('path');

const dialect = process.env.DB_DIALECT || 'sqlite';
const databaseUrl = process.env.DATABASE_URL || `sqlite:${path.join(__dirname, '../../dev.sqlite')}`;

const sequelize = new Sequelize(databaseUrl, {
  logging: false,
  dialectOptions: {},
});

const initModels = () => {
  const User = require('./user')(sequelize, DataTypes);
  const Profile = require('./profile')(sequelize, DataTypes);
  const Like = require('./like')(sequelize, DataTypes);
  const Message = require('./message')(sequelize, DataTypes);

  User.hasOne(Profile, { foreignKey: 'userId', as: 'profile' });
  Profile.belongsTo(User, { foreignKey: 'userId', as: 'user' });

  User.belongsToMany(User, { through: Like, as: 'likedUsers', foreignKey: 'fromUserId', otherKey: 'toUserId' });

  Message.belongsTo(User, { foreignKey: 'fromUserId', as: 'from' });
  Message.belongsTo(User, { foreignKey: 'toUserId', as: 'to' });

  module.exports = { sequelize, User, Profile, Like, Message };
};

module.exports = { sequelize, initModels };
