```javascript name=backend/src/routes/auth.js
const express = require('express');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const { sequelize, User, Profile } = require('../models');
const { Op } = require('sequelize');

const router = express.Router();

const JWT_SECRET = process.env.JWT_SECRET || 'dev_secret';

// Register
router.post('/register', async (req, res) => {
  try {
    const { email, password, name, dob } = req.body;
    if (!email || !password || !dob) return res.status(400).json({ error: 'email, password, dob required' });

    // server-side DOB >=18 check
    const born = new Date(dob);
    const age = Math.floor((Date.now() - born.getTime()) / (1000*60*60*24*365.25));
    if (age < 18) return res.status(403).json({ error: 'Must be 18 or older' });

    const hash = await bcrypt.hash(password, 10);
    const user = await User.create({ email, passwordHash: hash, name, dob });
    await Profile.create({ userId: user.id, age, avatarUrl: null });
    const token = jwt.sign({ id: user.id }, JWT_SECRET);
    res.json({ user: { id: user.id, email: user.email, name }, token });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'register failed' });
  }
});

// Login
router.post('/login', async (req, res) => {
  const { email, password } = req.body;
  const user = await User.findOne({ where: { email } });
  if (!user) return res.status(400).json({ error: 'Invalid credentials' });
  const ok = await bcrypt.compare(password, user.passwordHash);
  if (!ok) return res.status(400).json({ error: 'Invalid credentials' });
  const token = jwt.sign({ id: user.id }, JWT_SECRET);
  res.json({ token, user: { id: user.id, email: user.email, name: user.name } });
});

module.exports = router;
