import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { ProfileCard } from './components/ProfileCard';
import { SwipeButtons } from './components/SwipeButtons';
import { ChatBubble } from './components/ChatBubble';
import Login from './pages/Login';
import Premium from './pages/Premium';

const API = import.meta.env.VITE_API_URL || 'http://localhost:4000/api';

export default function App() {
  const [token, setToken] = useState<string | null>(localStorage.getItem('token'));
  const [profiles, setProfiles] = useState<any[]>([]);
  const [messages, setMessages] = useState<any[]>([]);

  useEffect(() => {
    if (token) {
      axios.defaults.headers.common['Authorization'] = `Bearer ${token}`;
      axios.get(`${API}/matches`).then(res => setProfiles(res.data));
    }
  }, [token]);

  if (!token) return <Login onLogin={(t: string) => { localStorage.setItem('token', t); setToken(t); }} />;

  const handleLike = async (toUserId: string) => {
    await axios.post(`${API}/matches/like`, { toUserId });
    setProfiles(p => p.slice(1));
  };
  const handleDislike = () => setProfiles(p => p.slice(1));

  return (
    <div style={{ padding: 20 }}>
      <h1>Pulse — Discover</h1>
      <div style={{ display: 'flex', gap: 20 }}>
        {profiles[0] ? <ProfileCard name={profiles[0].user?.name || 'Unknown'} age={profiles[0].age} imageUrl={profiles[0].avatarUrl || ''} /> : <div>No more profiles</div>}
      </div>
      <SwipeButtons onLike={() => handleLike(profiles[0]?.userId)} onDislike={handleDislike} />
      <h2>Chat (demo)</h2>
      <div style={{ display: 'flex', flexDirection: 'column' }}>
        {messages.map((m, i) => <ChatBubble key={i} message={m.message} isMe={m.fromUserId === 'me'} />)}
      </div>

      <Premium qrCodeUrl="https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=usdt:TXYZ1234" />
    </div>
  );
}
