import React, { useState } from 'react';
import axios from 'axios';

const API = import.meta.env.VITE_API_URL || 'http://localhost:4000/api';

export default function Login({ onLogin }: { onLogin: (token: string) => void }) {
  const [email, setEmail] = useState('sophie@example.com');
  const [password, setPassword] = useState('password');
  const [dob, setDob] = useState('1998-01-01');
  const [mode, setMode] = useState<'login'|'register'>('login');

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    try {
      if (mode === 'login') {
        const res = await axios.post(`${API}/auth/login`, { email, password });
        onLogin(res.data.token);
      } else {
        const res = await axios.post(`${API}/auth/register`, { email, password, dob, name: 'Demo' });
        onLogin(res.data.token);
      }
    } catch (err: any) {
      alert(err?.response?.data?.error || 'Error');
    }
  }

  return (
    <div className="login-screen">
      <form onSubmit={submit}>
        <input value={email} onChange={e=>setEmail(e.target.value)} placeholder="email" />
        <input value={password} onChange={e=>setPassword(e.target.value)} placeholder="password" />
        {mode === 'register' && <input type="date" value={dob} onChange={e=>setDob(e.target.value)} />}
        <button className="login-btn" type="submit">{mode === 'login' ? 'Login' : 'Register'}</button>
        <div style={{ marginTop: 10 }}>
          <button type="button" onClick={() => setMode(m => m === 'login' ? 'register' : 'login')}>{mode === 'login' ? 'Create account' : 'Have an account? Login'}</button>
        </div>
      </form>
    </div>
  );
}
