import React, { useState, useEffect } from 'react'
import axios from 'axios'
import Login from './components/Login'
import Profile from './components/Profile'

const API = import.meta.env.VITE_API_URL || 'http://localhost:8080/api'

export default function App() {
  const [token, setToken] = useState(localStorage.getItem('token') || '')
  const [user, setUser] = useState(null)
  const [matches, setMatches] = useState([])

  useEffect(() => {
    if (token) {
      axios.defaults.headers.common['Authorization'] = `Bearer ${token}`
      // fetch matches
      axios.get(`${API}/matches`).then(res => setMatches(res.data))
      // fetch user profile: the backend returns user in token endpoints; for demo we skip
    }
  }, [token])

  if (!token) {
    return <Login onLogin={(t) => { setToken(t); localStorage.setItem('token', t) }} />
  }

  return (
    <div style={{ padding: 20 }}>
      <h1>Pulse — Discover</h1>
      <Profile />
      <h2>Matches</h2>
      <ul>
        {matches.map(m => (
          <li key={m.id}>
            <strong>{m.user?.email}</strong> — {m.bio || 'No bio'}
          </li>
        ))}
      </ul>
      <button onClick={() => { localStorage.removeItem('token'); setToken(''); delete axios.defaults.headers.common['Authorization']; }}>Logout</button>
    </div>
  )
}

